class MedianFinder {
private:
    // 基于大小根堆的双顶栈结构，默认是 `max_size_st ➾ min_size_st`
    std::stack<int> max_size_st, min_size_st;

public:
    MedianFinder() {
    }

    // 添加数值 `num` 到双顶栈结构，并且保证双顶栈结构的大小关系
    void addNum(int num) {
        // 待入栈判断队列是否为空
        if (min_size_st.empty()) {
            min_size_st.push(num);
        } else if (min_size_st.top() > num) {
            max_size_st.push(num); // 大顶双向栈
        } else {
            min_size_st.push(num); // 小顶双向栈
        }

        // 大顶栈为空或者是最小顶栈元素个数小于最大顶栈个数, 将最大顶栈元素迁移到最小顶栈中
        // nums[nums_size] > nums[nums_size-1]; 
        while (max_size_st.size() - min_size_st.size() > 1) {
            min_size_st.push(max_size_st.top());
            max_size_st.pop();
        }

        // 最小顶栈为空或者是最小顶栈个数小于最大顶栈
        while (max_size_st.size() < min_size_st.size()) {
            max_size_st.push(min_size_st.top());
            min_size_st.pop();
        }
    }

    // 依据双顶栈的元素找到中位数
    double findMedian() {
        if (max_size_st.size() - min_size_st.size() == -1) {
            return min_size_st.top();
        }

        return (max_size_st.top() + min_size_st.top()) / 2.0;
    }
}
