\Rightarrow \sum_{k=1}^{\infty} \frac{k}{k^{2}-1}  
=\sum_{k=1}^{\infty} \frac{k}{(k-1)(k+1)}  
=2\sum_{k=2}^{\infty} \frac{1}{k-1}-2\sum_{k=1}^{\infty} \frac{1}{k+1}  
=2\sum_{k=1}^{\infty} \frac{1}{k}-2\sum_{k=2}^{\infty} \frac{1}{k}<4\sum_{k=1}^{\infty} \frac{1}{k^{3}}<4  
\end{gathered}  
$$  
